export function groupedRibbon(s,tabs,icon,availableMethods=supportedMethods){
 const selected=selectedObjects(activeBook(s.board)),context=selected.curve?'Curve':selected.track?'Track':selected.well?'Section':null;
 const current=ribbonGroups[s.ribbonTab]?s.ribbonTab:context===s.ribbonTab?context:'Home';
 const contextual=context==='Curve'?group('Selected curve',command('properties','Curve properties','settings',true),command('duplicate-curve','Duplicate overlay','plus'),command('provenance','Source and provenance','file'),command('curve-export','Export curve','download')):context==='Track'?group('Selected track',command('properties','Track properties','settings',true),command('duplicate-track','Duplicate track','plus'),command('empty-track','Add track','plus')):group('Selected section',command('properties','Section properties','settings',true),command('fit','Fit depth','logs'),command('markers','Review markers','pin'));
 const groups=ribbonGroups[current]||[contextual];
 const available=new Set(availableMethods.map(m=>m.id));
 const disabled=id=>id.startsWith('methods:')&&id!=='methods:all'&&!availableMethods.some(m=>m.tool===id.slice(8))?'This tool is unavailable for the selected study workflows.':id.startsWith('method:')&&!available.has(id.slice(7))?'This method is unavailable for the selected study workflows.':['empty-track'].includes(id)&&!selected.well?'Select a well first.':['duplicate-track'].includes(id)&&!selected.track?'Select a track first.':['duplicate-curve','provenance','curve-export'].includes(id)&&!selected.curve?'Select a curve first.':'';
 const button=c=>{const reason=c.unavailable||disabled(c.id);return `<button data-pp-action="${esc(c.id)}" class="pp-command ${c.primary?'pp-command-primary':''} ${['prepare','evaluate'].includes(c.id)?'pp-command-guided':''}" title="${esc(reason||c.label)}" ${reason?'disabled':''}>${icon(c.icon)}<span>${esc(c.label)}</span></button>`;};
 const content=g=>`<div class="pp-command-items">${g.commands.filter(c=>c.primary).map(button).join('')}<div class="pp-command-stack">${g.commands.filter(c=>!c.primary).map(button).join('')}</div></div>`;
 return `<nav class="pp-ribbon-tabs" role="tablist" aria-label="Petrophysics ribbon">${[...tabs,...(context?[context]:[])].map(t=>`<button role="tab" data-pp-tab="${t}" class="${t===context?'pp-context-tab':''}" aria-selected="${current===t}" aria-current="${current===t?'page':'false'}" aria-controls="pp-command-band">${t}</button>`).join('')}<button role="button" data-pp-action="collapse-ribbon" aria-label="${s.layout.ribbonCollapsed?'Expand':'Collapse'} ribbon" aria-expanded="${!s.layout.ribbonCollapsed}" title="${s.layout.ribbonCollapsed?'Expand':'Collapse'} ribbon">${icon(s.layout.ribbonCollapsed?'down':'menu')}</button></nav><div id="pp-command-band" class="pp-command-band" role="toolbar" aria-label="${current} commands" ${s.layout.ribbonCollapsed?'hidden':''}>${groups.map(g=>`<section class="pp-command-group" aria-label="${g.label}"><div class="pp-group-expanded">${content(g)}<div class="pp-group-caption">${g.label}</div></div><details class="pp-group-compact"><summary>${g.label}${icon('down')}</summary><div>${content(g)}</div></details></section>`).join('')}<section class="pp-command-group pp-methods-group"><button class="pp-command pp-command-primary" data-pp-action="methods:all">${icon('settings')}<span>Advanced methods</span></button><div class="pp-group-caption">All tools</div></section></div>`;
}

export function workspaceModal(host,title,body,footer){
 const old=document.querySelector('#dialog'),previous=old?.open?old._ppReturnFocus:document.activeElement;
 host.modal(title,body,footer);
 const dialog=document.querySelector('#dialog');dialog.style.setProperty('--pp-dialog-zoom',String(Number.parseFloat(getComputedStyle(document.documentElement).zoom)||1));dialog.classList.add('pp-dialog');dialog.setAttribute('aria-labelledby','pp-dialog-title');dialog.querySelector('h2').id='pp-dialog-title';
 dialog.classList.toggle('pp-dialog-wide',/review|workflow|comparison|associations|calibrat|prepar|report|method/i.test(title));dialog._ppReturnFocus=previous;
 // Keep controls in their original forms so existing listeners and submission semantics survive.
 for(const parent of [dialog.querySelector('.dialog-body'),...dialog.querySelectorAll('.dialog-body>form')]){
  if(!parent)continue;const actions=[...parent.children].filter(n=>n.tagName==='BUTTON');if(!actions.length)continue;
  const row=document.createElement('div');row.className='pp-dialog-actions';parent.append(row);for(const button of actions)row.append(button);
 }
 dialog.addEventListener('close',()=>{if(dialog.open)return;dialog.classList.remove('pp-dialog','pp-dialog-wide');dialog.removeAttribute('aria-labelledby');if(previous?.isConnected)previous.focus();},{once:true});
}
